return {
  name    = "declaration",
  version = "1.7.3",
  summary = "Haliade system declarative system configuration (haliade-sync)",
  url     = "https://raw.githubusercontent.com/gretagen/zeta-constructs/refs/heads/main/packages/declaration/declaration-1.7.3.tar.gz",
  sha256  = "43230920ad7756e7a8e1cfd91cabb3a1f9b4a828cf0b6a497e4e603d41bd806c",
  deps    = { "lua", "chronos" },
  archive = { strip = 1 },
  test    = function(p)
    p:run("test -x " .. p.install_root .. "/usr/bin/haliade-sync && test -f " .. p.install_root .. "/usr/lib/declaration/sync.lua && test -f " .. p.install_root .. "/usr/lib/declaration/plugins.lua && test -d " .. p.install_root .. "/usr/lib/declaration/generators && test -f " .. p.install_root .. "/usr/lib/declaration/iniswap/dinit.sh && test -f " .. p.install_root .. "/usr/lib/declaration/iniswap/systemd.sh && test -f " .. p.install_root .. "/usr/lib/declaration/generators/sysmd-services.lua && lua -e 'package.path=\"" .. p.install_root .. "/usr/lib/declaration/?.lua;\" .. package.path; local p=require(\"plugins\"); local l=p.enabled_generators(\"/nonexistent/enabled_modules.lua\"); assert(type(l)==\"table\" and #l>=20)' && printf '%s\\n' 'local enabled_generators = {' '\"edit\",' '\"ssh\",' '}' > enabled.lua && lua -e 'package.path=\"" .. p.install_root .. "/usr/lib/declaration/?.lua;\" .. package.path; local p=require(\"plugins\"); local l=p.enabled_generators(\"enabled.lua\"); assert(#l==2 and l[1]==\"edit\" and l[2]==\"ssh\")' && mkdir -p pc && printf '%s\\n' 'defaults[\"nixpkgs\"] = {}' 'schema[\"nixpkgs\"] = \"table\"' > pc/nixpkgs.lua && printf '%s\\n' 'return { [\"nixpkgs\"] = { \"nixpkgs#fastfetch\" } }' > def.lua && lua -e 'package.path=\"" .. p.install_root .. "/usr/lib/declaration/?.lua;\" .. package.path; local c=require(\"config\"); local cfg=assert(c.load(\"def.lua\", \"pc\")); assert(cfg[\"nixpkgs\"][1]==\"nixpkgs#fastfetch\")' && printf '%s\\n' 'local x = (' > pc/broken.lua && lua -e 'package.path=\"" .. p.install_root .. "/usr/lib/declaration/?.lua;\" .. package.path; local c=require(\"config\"); local _,err=c.load(\"def.lua\", \"pc\"); assert(err and err:find(\"broken.lua\"))' && lua -e 'package.path=\"" .. p.install_root .. "/usr/lib/declaration/generators/?.lua;\" .. package.path; local g=require(\"users\"); local P=\"root:x:0:0:root:/root:/bin/bash\\n\"..\"alice:x:1000:1000:Alice:/home/alice:/bin/thesh\\n\"; local G=\"wheel:x:10:root,alice\\n\"..\"audio:x:29:pulse,alice\\n\"..\"video:x:44:alice\\n\"..\"tty:x:5:root,alice\\n\"..\"input:x:106:\\n\"; local function mk() local s={ch={}}; s.read_file=function(p) if p==\"/etc/passwd\" then return P end if p==\"/etc/group\" then return G end return nil end; s.change=function(t,sec,tgt,det) local c={type=t,section=sec,target=tgt,detail=det}; table.insert(s.ch,c); return c end; s.shell=function() return true end; s.ensure_dir=function() return true end; s.write_file=function() return true end; return s end; local s=mk(); local cfg={users={alice={groups={\"wheel\",\"audio\",\"video\",\"tty\",\"input\"}}}}; g.plan(cfg,s); assert(#s.ch==1 and s.ch[1].type==\"~\" and s.ch[1].target==\"alice groups\" and s.ch[1].detail==\"wheel,audio,video,tty,input\", \"drift\"); local s2=mk(); g.plan({users={alice={groups={\"wheel\",\"audio\",\"video\",\"tty\"},shell=\"/bin/thesh\"}}},s2); assert(#s2.ch==0, \"no-drift\"); local s3=mk(); g.plan({users={alice={shell=\"/bin/bash\"}}},s3); assert(#s3.ch==1 and s3.ch[1].target==\"alice shell\", \"shell\"); local s4=mk(); g.plan({users={alice={groups={\"wheel\",\"ghost\"}}}},s4); assert(#s4.ch==0, \"missing-group\"); print(\"users convergence OK\")'")
  end,
}
